import {PackDemo,WORLD} from './pack-demo-model.mjs';
import {drawProjectile} from './projectile-effects.mjs';
const $=id=>document.getElementById(id),canvas=$('arena'),c=canvas.getContext('2d');
export const demo=new PackDemo();
let fireEnabled=true,keys=new Set(),aim=null,joy={x:0,y:0},last=0,ratio=1,offsetX=0,offsetY=0,viewportW=1100,viewportH=720,previousMessage='',previousState='',previousBursts=0,toastUntil=0;
function clearInput(){keys.clear();joy={x:0,y:0};aim=null;$('stick').style.transform='translate(0,0)'}
function start(){if(demo.state==='ready')demo.start();else if(demo.state==='paused')demo.state='playing';else{fireEnabled=true;demo.reset();demo.start()}last=performance.now();clearInput();sync();canvas.focus({preventScroll:true})}
function reset(){fireEnabled=true;demo.reset();clearInput();previousBursts=0;toastUntil=0;sync()}
function pause(){if(demo.state==='playing'){demo.state='paused';clearInput()}else if(demo.state==='paused'){demo.state='playing';last=performance.now()}sync()}
function toggleFire(){fireEnabled=!fireEnabled;sync()}
$('fireToggle').onclick=toggleFire;
$('start').onclick=start;$('restart').onclick=reset;$('pause').onclick=pause;$('attachment').onclick=()=>{demo.togglePack();sync()};
window.addEventListener('keydown',e=>{if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' '].includes(e.key))e.preventDefault();const k=e.key.toLowerCase();if((k===' '||k==='escape')&&!e.repeat)pause();else if(k==='f'&&!e.repeat)toggleFire();else if(k==='q'&&!e.repeat){demo.togglePack();sync()}else keys.add(k)});window.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));window.addEventListener('blur',()=>{if(demo.state==='playing'){demo.state='paused';sync()}clearInput()});document.addEventListener('visibilitychange',()=>{if(document.hidden&&demo.state==='playing'){demo.state='paused';clearInput();sync()}});
canvas.addEventListener('pointermove',e=>{if(e.pointerType==='touch')return;const r=canvas.getBoundingClientRect();aim={x:(e.clientX-r.left-offsetX)/ratio,y:(e.clientY-r.top-offsetY)/ratio}});canvas.addEventListener('pointerleave',()=>aim=null);
let joyPointer=null;function moveJoy(e){const r=$('joystick').getBoundingClientRect(),dx=e.clientX-r.left-r.width/2,dy=e.clientY-r.top-r.height/2,d=Math.hypot(dx,dy)||1,f=Math.min(d,28)/d;joy={x:dx*f/28,y:dy*f/28};$('stick').style.transform=`translate(${dx*f}px,${dy*f}px)`}
$('joystick').addEventListener('pointerdown',e=>{if(joyPointer!==null)return;e.preventDefault();joyPointer=e.pointerId;$('joystick').setPointerCapture(e.pointerId);moveJoy(e)});$('joystick').addEventListener('pointermove',e=>{if(e.pointerId===joyPointer)moveJoy(e)});for(const name of ['pointerup','pointercancel','lostpointercapture'])$('joystick').addEventListener(name,e=>{if(e.pointerId!==joyPointer)return;joyPointer=null;joy={x:0,y:0};$('stick').style.transform='translate(0,0)'});
function sync(){const state=demo.state,p=demo.player;$('fireToggle').textContent=fireEnabled?'停止开火':'继续开火';$('fireToggle').setAttribute('aria-pressed',String(fireEnabled));$('hp').textContent=Math.ceil(p.hp);$('hpFill').style.width=p.hp+'%';$('clock').textContent=Math.max(0,Math.ceil(60-demo.time));$('kills').textContent=demo.kills;$('bursts').textContent=demo.bursts;$('waterKills').textContent=demo.waterKills;$('chargeValue').textContent=Math.floor(demo.charge*100)+'%';$('waterFill').style.width=demo.charge*100+'%';$('chargeLabel').textContent=demo.spraying>0?'正在喷水':'蓄水';$('tankName').textContent=demo.equipped?'冷凝水包':'未安装配件';$('tankStatus').textContent=!demo.equipped?'水蒸气散去 · 不再收集':demo.spraying>0?(fireEnabled?'喷水消耗中 · 主枪同时补水':'喷水消耗中 · 停火不补水'):demo.charge>0?'收集水蒸气 → 冷凝 → 蓄水':'空包 · 正在等待收集';$('attachment').textContent=demo.equipped?'拆下水包':'装上空水包';$('attachment').setAttribute('aria-pressed',String(demo.equipped));$('pause').textContent=state==='paused'?'继续 ▷':'暂停 Ⅱ';$('pause').disabled=!['playing','paused'].includes(state);
 if(previousMessage!==demo.message){$('feedback').textContent=demo.message;previousMessage=demo.message}if(demo.bursts>previousBursts){toastUntil=performance.now()+1600;previousBursts=demo.bursts}$('burstToast').classList.toggle('active',state==='playing'&&performance.now()<toastUntil);
 if(previousState!==state){previousState=state;$('banner').classList.toggle('hidden',state==='playing');if(state==='ready'){$('bannerTitle').innerHTML='你负责喷火，<br>水包负责背后。';$('bannerText').innerHTML='自动开火、自动瞄准。用 WASD / 方向键移动。<br>移动鼠标可手动瞄准，触屏拖动左下摇杆。';$('start').textContent='进入试验场 →'}else if(state==='paused'){$('bannerTitle').textContent='喘口气，再继续。';$('bannerText').textContent='喷火、蓄水和怪物都已暂停。';$('start').textContent='继续战斗 →'}else if(state==='won'||state==='dead'){$('bannerTitle').textContent=state==='won'?'火力，接上了。':'再绕大一点试试。';$('bannerText').textContent=`击败 ${demo.kills} 只 · 水包释放 ${demo.bursts} 次 · 水流击败 ${demo.waterKills} 只。试试拆下水包，对比战斗的变化。`;$('start').textContent='再试一次 →'}}
}
function circle(x,y,r,fill){c.beginPath();c.arc(x,y,r,0,Math.PI*2);c.fillStyle=fill;c.fill()}
function render(now){const rect=canvas.getBoundingClientRect(),dpr=Math.min(globalThis.devicePixelRatio||1,2);viewportW=rect.width;viewportH=rect.height;const w=Math.round(rect.width*dpr),h=Math.round(rect.height*dpr);if(canvas.width!==w||canvas.height!==h){canvas.width=w;canvas.height=h}ratio=Math.min(rect.width/WORLD.w,rect.height/WORLD.h);offsetX=(rect.width-WORLD.w*ratio)/2;offsetY=(rect.height-WORLD.h*ratio)/2;c.setTransform(dpr,0,0,dpr,0,0);c.fillStyle='#0b141c';c.fillRect(0,0,viewportW,viewportH);c.translate(offsetX,offsetY);c.scale(ratio,ratio);c.save();c.beginPath();c.rect(0,0,WORLD.w,WORLD.h);c.clip();c.fillStyle='#11212a';c.fillRect(0,0,WORLD.w,WORLD.h);c.strokeStyle='#27434c55';c.lineWidth=1;for(let x=0;x<WORLD.w;x+=44){c.beginPath();c.moveTo(x,0);c.lineTo(x,WORLD.h);c.stroke()}for(let y=0;y<WORLD.h;y+=44){c.beginPath();c.moveTo(0,y);c.lineTo(WORLD.w,y);c.stroke()}c.strokeStyle='#466773';c.strokeRect(1,1,WORLD.w-2,WORLD.h-2);
 for(const e of demo.enemies){c.save();c.translate(e.x,e.y);const wobble=Math.sin(now*.005+e.id)*2;if(e.type==='metal'){c.rotate(now*.0005+e.id);c.fillStyle=e.hit>0?'#e9f9ff':'#d1b48a';c.beginPath();for(let i=0;i<6;i++){const a=i*Math.PI/3;c.lineTo(Math.cos(a)*e.r,Math.sin(a)*e.r)}c.closePath();c.fill()}else{c.fillStyle=e.hit>0?'#e9f9ff':'#8ca7b4';c.beginPath();c.ellipse(0,0,e.r+wobble,e.r-wobble,0,0,Math.PI*2);c.fill()}c.restore();circle(e.x-4,e.y-2,2,'#14232b');circle(e.x+4,e.y-2,2,'#14232b');if(e.hp<e.maxHp){c.fillStyle='#233944';c.fillRect(e.x-15,e.y-e.r-9,30,3);c.fillStyle=e.burn>0?'#b5e6ff':'#a7cdd9';c.fillRect(e.x-15,e.y-e.r-9,30*Math.max(0,e.hp/e.maxHp),3)}if(e.burn>0){for(let i=0;i<3;i++){const a=now*.003+i*2;circle(e.x+Math.cos(a)*e.r,e.y+Math.sin(a)*e.r,3,'#aee4ff')}}}
 const p=demo.player;if(demo.firing&&demo.state==='playing')drawProjectile(c,{type:'flame',visual:'cone',x:p.x+Math.cos(p.angle)*22,y:p.y+Math.sin(p.angle)*22,originX:p.x,originY:p.y,angle:p.angle,length:190,halfAngle:.5,life:.4,duration:.4},now/1000);
 for(const w of demo.water){const alpha=Math.min(1,w.life*5);c.globalAlpha=alpha;c.strokeStyle='#2e9ac9';c.lineWidth=12;c.lineCap='round';c.beginPath();c.moveTo(w.x-w.vx*.055,w.y-w.vy*.055);c.lineTo(w.x,w.y);c.stroke();c.strokeStyle='#bcf5ff';c.lineWidth=3;c.beginPath();c.moveTo(w.x-w.vx*.035,w.y-w.vy*.035);c.lineTo(w.x,w.y);c.stroke()}c.globalAlpha=1;
 for(const s of demo.sparks){c.globalAlpha=s.life*2;for(let i=0;i<6;i++){const a=i*Math.PI/3,r=(.5-s.life)*70;circle(s.x+Math.cos(a)*r,s.y+Math.sin(a)*r,s.kind==='water'?3:2,s.kind==='water'?'#98e6ff':'#b2e7c9')}}c.globalAlpha=1;
 circle(p.x,p.y+9,21,'#0005');c.save();c.translate(p.x,p.y);c.rotate(p.angle);if(demo.equipped){c.fillStyle='#183e52';c.fillRect(-23,-13,13,26);c.fillStyle='#81def4';c.fillRect(-21,11-22*demo.charge,9,22*demo.charge);c.strokeStyle='#76aebe';c.lineWidth=1.5;c.strokeRect(-23,-13,13,26)}circle(0,0,17,demo.hurt>0?'#f9c5b1':'#d2e8db');circle(3,-5,3,'#1d343e');circle(3,5,3,'#1d343e');c.fillStyle='#718d9e';c.fillRect(10,-6,21,12);c.fillStyle='#cee9f8';c.fillRect(27,-4,6,8);c.restore();
 if(demo.equipped&&demo.firing&&demo.spraying===0&&demo.state==='playing'){for(let i=0;i<5;i++){const f=(now*.0005+i*.2)%1;circle(p.x-Math.cos(p.angle)*20+Math.sin(f*7+i)*7,p.y-20-f*24,2.5*(1-f),'#bcdeec88')}c.strokeStyle='#8cdef555';c.lineWidth=2;c.beginPath();c.arc(p.x,p.y,27,-Math.PI/2,-Math.PI/2+Math.PI*2*demo.charge);c.stroke()}
 c.restore();
}
function frame(now){const dt=last?Math.min((now-last)/1000,.04):0;last=now;demo.step(dt,{x:(keys.has('d')||keys.has('arrowright')?1:0)-(keys.has('a')||keys.has('arrowleft')?1:0)+joy.x,y:(keys.has('s')||keys.has('arrowdown')?1:0)-(keys.has('w')||keys.has('arrowup')?1:0)+joy.y,aim,fire:fireEnabled});sync();render(now);requestAnimationFrame(frame)}sync();requestAnimationFrame(frame);
